    for color in range(2,10):
        seeds=[(r,c) for r in range(h) for c in range(w) if a[r][c]==color]
        if not seeds: continue
        for sr,sc in seeds:
            # identify 3x3 tile origin aligned around seed location, tile dimensions based on marker relative offset in regular 3x3 objects
